'use strict';

const path = require('path');
const cds = require('@sap/cds');
const { UPGRADE_DIR } = require('../../../constants');

const EXCLUDE_DIRS = new Set(['node_modules', '.git', 'gen', 'dist', UPGRADE_DIR]);
const EXCLUDE_FILES = new Set([
  'package-lock.json', 'yarn.lock', 'pnpm-lock.yaml', 'npm-shrinkwrap.json',
]);
const EXCLUDE_EXTS = new Set(['.md']);

const CONFIG_NAMES = new Set([
  'package.json', '.cdsrc', '.cdsrc.json', '.cdsrc.js', '.cdsrc.yaml',
  '.cdsrc-private.json', 'cds.config.js', 'cds.config.json',
  '.env', 'default-env.json',
]);

function discoverProjectFiles(root) {
  const fs = cds.utils.fs;
  const cdl = [];
  const source = [];
  const config = [];
  const other = [];

  function walk(dir) {
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      if (EXCLUDE_DIRS.has(entry.name)) continue;
      if (EXCLUDE_FILES.has(entry.name)) continue;
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile()) {
        if (EXCLUDE_EXTS.has(path.extname(entry.name))) continue;
        classify(full, entry.name, { cdl, source, config, other });
      }
    }
  }

  walk(root);
  return {
    cdl,
    source,
    config,
    other,
  };
}

function classify(fullPath, name, buckets) {
  const ext = path.extname(name);
  if (ext === '.cds') {
    buckets.cdl.push(fullPath);
    return;
  }
  if (ext === '.js' || ext === '.ts' || ext === '.mjs' || ext === '.cjs') {
    buckets.source.push(fullPath);
    return;
  }
  if (CONFIG_NAMES.has(name)) {
    buckets.config.push(fullPath);
    return;
  }
  buckets.other.push(fullPath);
}

function buildFileCache(fileSets) {
  const fs = cds.utils.fs;
  const cache = new Map();
  for (const files of fileSets) {
    for (const file of files) {
      if (cache.has(file)) continue;
      try { cache.set(file, fs.readFileSync(file, 'utf8')); } catch { cache.set(file, null); }
    }
  }
  return cache;
}

async function findPackageJsonFiles() {
  const { exec } = require('child_process');
  const { promisify } = require('util');
  const execAsync = promisify(exec);
  const fs = cds.utils.fs;
  const exists = cds.utils.exists;
  const files = [path.join(cds.root, 'package.json')];
  const entries = fs.readdirSync(cds.root, { withFileTypes: true });

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
    const subPkgPath = path.join(cds.root, entry.name, 'package.json');
    if (!exists(subPkgPath)) continue;
    const ignored = await isGitIgnored(subPkgPath, cds.root, execAsync);
    if (!ignored) files.push(subPkgPath);
  }

  return files;
}

async function isGitIgnored(filePath, cwd, execAsync) {
  try {
    await execAsync(`git check-ignore -q "${filePath}"`, { cwd });
    return true;
  } catch {
    return false;
  }
}

module.exports = {
  discoverProjectFiles,
  buildFileCache,
  findPackageJsonFiles,
};
